#!/usr/bin/env python3
from pathlib import Path
import sys
MARK='NATIVEBOOT2-B43-TFXSERVERDIAG1'
def fail(m): raise SystemExit(f'{MARK}: {m}')
def rep(t,o,n,label):
    c=t.count(o)
    if c!=1: fail(f'{label}: expected one anchor, found {c}')
    return t.replace(o,n,1)
def main():
    up=Path(sys.argv[1]).resolve()
    svc=up/'kernel/src/svc.cpp' if (up/'kernel/src/svc.cpp').exists() else up/'src/emu/kernel/src/svc.cpp'
    loader=up/'services/src/loader/loader.cpp' if (up/'services/src/loader/loader.cpp').exists() else up/'src/emu/services/src/loader/loader.cpp'
    sa=up/'services/src/sms/sa/sa.cpp' if (up/'services/src/sms/sa/sa.cpp').exists() else up/'src/emu/services/src/sms/sa/sa.cpp'
    s=svc.read_text(); l=loader.read_text(); sat=sa.read_text()
    for g,where in (('[NBOOT2][SA_HWRM_ABI]',sat),('[NBOOT2][LOADER_PDD]',l),('[NBOOT2][EIKFEP_STATE]',s)):
        if g not in where: fail('missing baseline '+g)
    if '[NBOOT2][TFX_SESSION]' in s: print('already'); return
    anchor='''    static thread_local v11_last_ipc_context v11_last_ipc;\n\n'''
    block='''    static thread_local v11_last_ipc_context v11_last_ipc;\n\n    // NATIVEBOOT2-B43 TFXSERVERDIAG1: host-only provenance for an exact\n    // TfxServer CreateSession miss. It never changes guest kernel state.\n    struct b43_tfx_miss_context {\n        bool valid{ false };\n        kernel::process *process{ nullptr };\n        kernel::thread *thread{ nullptr };\n        std::uint32_t pc{ 0 };\n        std::uint32_t lr{ 0 };\n        std::uint32_t sp{ 0 };\n        std::int32_t msg_slots{ 0 };\n        std::int32_t mode{ 0 };\n    };\n    static thread_local b43_tfx_miss_context b43_tfx_miss;\n\n'''
    s=rep(s,anchor,block,'b43 state')

    old='''    BRIDGE_FUNC(std::int32_t, session_create, eka2l1::ptr<desc8> server_name_des, std::int32_t msg_slot, eka2l1::ptr<void> sec, std::int32_t mode) {\n        process_ptr pr = kern->crr_process();\n\n        const std::string server_name = server_name_des.get(pr)->to_std_string(pr);\n        server_ptr server = kern->get_by_name<service::server>(server_name);\n\n        if (!server) {\n            LOG_TRACE(KERNEL, "Create session to unexist server: {}", server_name);\n            if (kern->get_config()->native_phone_boot) {\n                LOG_WARN(KERNEL, "[NBOOT2][MISSING_SERVER] process={} server={} msg_slots={} mode={}",\n                    pr->name(), server_name, msg_slot, mode);\n            }\n            return epoc::error_not_found;\n        }\n\n        return do_create_session_from_server(kern, server, msg_slot, sec, mode);\n    }\n'''
    new='''    BRIDGE_FUNC(std::int32_t, session_create, eka2l1::ptr<desc8> server_name_des, std::int32_t msg_slot, eka2l1::ptr<void> sec, std::int32_t mode) {\n        process_ptr pr = kern->crr_process();\n\n        const std::string server_name = server_name_des.get(pr)->to_std_string(pr);\n        const bool b43_tfx = kern->get_config()->native_phone_boot && (server_name == "TfxServer");\n        kernel::thread *b43_thr = kern->crr_thread();\n        auto *b43_cpu = kern->get_cpu();\n\n        if (b43_tfx && pr && b43_thr && b43_cpu) {\n            const auto uids = pr->get_uid_type();\n            const std::uint32_t uid3 = static_cast<std::uint32_t>(std::get<2>(uids));\n            const std::uint32_t pc = b43_cpu->get_pc();\n            const std::uint32_t lr = b43_cpu->get_reg(14);\n            const std::uint32_t sp = b43_cpu->get_reg(13);\n            b43_tfx_miss = { false, pr, b43_thr, pc, lr, sp, msg_slot, mode };\n\n            LOG_WARN(KERNEL,\n                "[NBOOT2][TFX_SESSION] phase=request process={} uid=0x{:08X} thread={} server={} msg_slots={} mode={} sec=0x{:08X} pc=0x{:08X} lr=0x{:08X} sp=0x{:08X}",\n                pr->name(), uid3, b43_thr->name(), server_name, msg_slot, mode,\n                sec.ptr_address(), pc, lr, sp);\n\n            auto b43_log_frame = [&](const char *kind, const std::uint32_t raw) {\n                const std::uint32_t addr = raw & ~1U;\n                codeseg_ptr seg = get_codeseg_from_addr(kern, pr, addr, false);\n                if (seg) {\n                    const std::uint32_t base = seg->get_code_run_addr(pr);\n                    LOG_WARN(KERNEL,\n                        "[NBOOT2][TFX_SESSION_FRAME] kind={} raw=0x{:08X} module={} base=0x{:08X} offset=0x{:08X}",\n                        kind, raw, common::ucs2_to_utf8(seg->get_full_path()), base, addr - base);\n                } else {\n                    LOG_WARN(KERNEL,\n                        "[NBOOT2][TFX_SESSION_FRAME] kind={} raw=0x{:08X} module=<unresolved>", kind, raw);\n                }\n            };\n            b43_log_frame("pc", pc);\n            b43_log_frame("lr", lr);\n\n            for (std::uint32_t i = 0; i < 24; ++i) {\n                const std::uint32_t slot_addr = sp + i * sizeof(std::uint32_t);\n                if (slot_addr < sp) break;\n                const std::uint32_t *slot = eka2l1::ptr<std::uint32_t>(slot_addr).get(pr);\n                if (!slot) break;\n                const std::uint32_t raw = *slot;\n                const std::uint32_t addr = raw & ~1U;\n                codeseg_ptr seg = addr >= 0x10000U ? get_codeseg_from_addr(kern, pr, addr, false) : nullptr;\n                if (seg) {\n                    const std::uint32_t base = seg->get_code_run_addr(pr);\n                    LOG_WARN(KERNEL,\n                        "[NBOOT2][TFX_SESSION_STACK] index={} slot=0x{:08X} raw=0x{:08X} module={} base=0x{:08X} offset=0x{:08X}",\n                        i, slot_addr, raw, common::ucs2_to_utf8(seg->get_full_path()), base, addr - base);\n                }\n            }\n        }\n\n        server_ptr server = kern->get_by_name<service::server>(server_name);\n\n        if (!server) {\n            LOG_TRACE(KERNEL, "Create session to unexist server: {}", server_name);\n            if (kern->get_config()->native_phone_boot) {\n                LOG_WARN(KERNEL, "[NBOOT2][MISSING_SERVER] process={} server={} msg_slots={} mode={}",\n                    pr->name(), server_name, msg_slot, mode);\n            }\n            if (b43_tfx) {\n                b43_tfx_miss.valid = true;\n                LOG_WARN(KERNEL,\n                    "[NBOOT2][TFX_SESSION] phase=missing process={} thread={} server={} result={} behavior=UNCHANGED_KErrNotFound",\n                    pr ? pr->name() : std::string("<null>"),\n                    b43_thr ? b43_thr->name() : std::string("<null>"),\n                    server_name, epoc::error_not_found);\n            }\n            return epoc::error_not_found;\n        }\n\n        if (b43_tfx) {\n            b43_tfx_miss.valid = false;\n            LOG_WARN(KERNEL,\n                "[NBOOT2][TFX_SESSION] phase=found process={} thread={} server={} server_hle={} behavior=UNCHANGED",\n                pr ? pr->name() : std::string("<null>"),\n                b43_thr ? b43_thr->name() : std::string("<null>"),\n                server_name, server->is_hle() ? 1 : 0);\n        }\n\n        return do_create_session_from_server(kern, server, msg_slot, sec, mode);\n    }\n'''
    s=rep(s,old,new,'session_create')

    anchor2='''        const std::int32_t leave_code = static_cast<std::int32_t>(kern->get_cpu()->get_reg(0));\n'''
    corr='''        if (menuui6_leave_code == epoc::error_not_found && b43_tfx_miss.valid\n            && b43_tfx_miss.process == menuui6_pr && b43_tfx_miss.thread == thr) {\n            const std::uint32_t now_pc = menuui6_cpu ? menuui6_cpu->get_pc() : 0U;\n            const std::uint32_t now_lr = menuui6_cpu ? menuui6_cpu->get_reg(14) : 0U;\n            LOG_WARN(KERNEL,\n                "[NBOOT2][TFX_LEAVE] correlated=1 process={} thread={} leave_code={} miss_pc=0x{:08X} miss_lr=0x{:08X} miss_sp=0x{:08X} now_pc=0x{:08X} now_lr=0x{:08X} msg_slots={} mode={} behavior=DIAGNOSTIC_ONLY",\n                menuui6_pr->name(), thr->name(), menuui6_leave_code,\n                b43_tfx_miss.pc, b43_tfx_miss.lr, b43_tfx_miss.sp, now_pc, now_lr,\n                b43_tfx_miss.msg_slots, b43_tfx_miss.mode);\n            b43_tfx_miss.valid = false;\n        }\n\n        const std::int32_t leave_code = static_cast<std::int32_t>(kern->get_cpu()->get_reg(0));\n'''
    s=rep(s,anchor2,corr,'leave correlation')

    reganchor='''        if (handle != kernel::INVALID_HANDLE) {\n            LOG_TRACE(KERNEL, "Server {} created", server_name);\n'''
    regnew='''        if (handle != kernel::INVALID_HANDLE) {\n            LOG_TRACE(KERNEL, "Server {} created", server_name);\n            if (kern->get_config()->native_phone_boot\n                && (server_name == "TfxServer"\n                    || crr_pr->name().find("alfred") != std::string::npos\n                    || crr_pr->name().find("Alfred") != std::string::npos\n                    || crr_pr->name().find("tfx") != std::string::npos\n                    || crr_pr->name().find("Tfx") != std::string::npos)) {\n                LOG_WARN(KERNEL,\n                    "[NBOOT2][TFX_SERVER_REGISTER] process={} server={} handle={} mode={} behavior=OBSERVE_ONLY",\n                    crr_pr->name(), server_name, handle, mode);\n            }\n'''
    s=rep(s,reganchor,regnew,'server register scan')

    panchor='''        LOG_TRACE(SERVICE_LOADER, "Trying to summon: {}", name_process);\n\n'''
    pnew='''        LOG_TRACE(SERVICE_LOADER, "Trying to summon: {}", name_process);\n\n        const std::string b43_process_path = common::ucs2_to_utf8(*process_name16);\n        const bool b43_tfx_process =\n            name_process.find("tfx") != std::string::npos || name_process.find("Tfx") != std::string::npos\n            || name_process.find("alfred") != std::string::npos || name_process.find("Alfred") != std::string::npos;\n        if (b43_tfx_process && ctx.sys->get_config()->native_phone_boot) {\n            kernel::process *caller = ctx.msg->own_thr ? ctx.msg->own_thr->owning_process() : nullptr;\n            LOG_WARN(SERVICE_LOADER,\n                "[NBOOT2][TFX_RESOLVE] kind=process phase=request caller={} path={} file={} uid3=0x{:08X} stack=0x{:X} behavior=OBSERVE_ONLY",\n                caller ? caller->name() : std::string("<null>"), b43_process_path, name_process, uid3, stack_size);\n        }\n\n'''
    l=rep(l,panchor,pnew,'loader process request')

    failanchor='''        if (!pr) {\n            LOG_DEBUG(SERVICE_LOADER, "Try spawning process {} failed", name_process);\n            ctx.complete(epoc::error_not_found);\n            return;\n        }\n'''
    failnew='''        if (!pr) {\n            LOG_DEBUG(SERVICE_LOADER, "Try spawning process {} failed", name_process);\n            if (b43_tfx_process && ctx.sys->get_config()->native_phone_boot) {\n                LOG_WARN(SERVICE_LOADER,\n                    "[NBOOT2][TFX_RESOLVE] kind=process phase=result path={} success=0 completion={} behavior=OBSERVE_ONLY",\n                    b43_process_path, epoc::error_not_found);\n            }\n            ctx.complete(epoc::error_not_found);\n            return;\n        }\n        if (b43_tfx_process && ctx.sys->get_config()->native_phone_boot) {\n            LOG_WARN(SERVICE_LOADER,\n                "[NBOOT2][TFX_RESOLVE] kind=process phase=result path={} success=1 spawned={} behavior=OBSERVE_ONLY",\n                b43_process_path, pr->name());\n        }\n'''
    l=rep(l,failanchor,failnew,'loader process result')

    lanchor='''        kernel::process *own_pr = ctx.msg->own_thr->owning_process();\n        const bool nativeboot2_root_diag =\n'''
    lnew='''        kernel::process *own_pr = ctx.msg->own_thr->owning_process();\n        const std::string b43_lib_path = common::ucs2_to_utf8(*lib_path);\n        const bool b43_tfx_library =\n            lib_name.find("tfx") != std::string::npos || lib_name.find("Tfx") != std::string::npos\n            || lib_name.find("alfred") != std::string::npos || lib_name.find("Alfred") != std::string::npos\n            || lib_name.find("transition") != std::string::npos || lib_name.find("Transition") != std::string::npos;\n        if (b43_tfx_library && ctx.sys->get_config()->native_phone_boot) {\n            LOG_WARN(SERVICE_LOADER,\n                "[NBOOT2][TFX_RESOLVE] kind=library phase=request process={} path={} file={} behavior=OBSERVE_ONLY",\n                own_pr ? own_pr->name() : std::string("<null>"), b43_lib_path, lib_name);\n        }\n        const bool nativeboot2_root_diag =\n'''
    l=rep(l,lanchor,lnew,'loader library request')

    lf='''        if (!cs) {\n            LOG_WARN(SERVICE_LOADER,\n                "[NBOOT2][LDR_LIB_RESULT] process={} request_path={} rooted_no_drive={} success=0 completion={}",\n'''
    lfn='''        if (!cs) {\n            if (b43_tfx_library && ctx.sys->get_config()->native_phone_boot) {\n                LOG_WARN(SERVICE_LOADER,\n                    "[NBOOT2][TFX_RESOLVE] kind=library phase=result process={} path={} success=0 completion={} behavior=OBSERVE_ONLY",\n                    own_pr ? own_pr->name() : std::string("<null>"), b43_lib_path, epoc::error_not_found);\n            }\n            LOG_WARN(SERVICE_LOADER,\n                "[NBOOT2][LDR_LIB_RESULT] process={} request_path={} rooted_no_drive={} success=0 completion={}",\n'''
    l=rep(l,lf,lfn,'loader library fail')

    create='''        auto lib_handle_and_obj = ctx.sys->get_kernel_system()->create_and_add_thread<kernel::library>(\n            static_cast<kernel::owner_type>(handle_owner), ctx.msg->own_thr, cs);\n\n        LOG_TRACE(SERVICE_LOADER, "Loaded library: {}", lib_name);\n'''
    createn='''        auto lib_handle_and_obj = ctx.sys->get_kernel_system()->create_and_add_thread<kernel::library>(\n            static_cast<kernel::owner_type>(handle_owner), ctx.msg->own_thr, cs);\n\n        LOG_TRACE(SERVICE_LOADER, "Loaded library: {}", lib_name);\n        if (b43_tfx_library && ctx.sys->get_config()->native_phone_boot) {\n            LOG_WARN(SERVICE_LOADER,\n                "[NBOOT2][TFX_RESOLVE] kind=library phase=result process={} path={} success=1 handle=0x{:08X} behavior=OBSERVE_ONLY",\n                own_pr ? own_pr->name() : std::string("<null>"), b43_lib_path, lib_handle_and_obj.first);\n        }\n'''
    l=rep(l,create,createn,'loader library success')

    svc.write_text(s); loader.write_text(l)
    print(MARK+': applied')
if __name__=='__main__': main()
